    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    // Initialize accumulator
    float sum = 0.0f;

    // Loop over tiles with unrolling
    int numTiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < numTiles; t += UNROLL_FACTOR) {
        // Preload multiple tiles
        for (int u = 0; u < UNROLL_FACTOR; u++) {
            int tileIdx = t + u;
            if (tileIdx < numTiles) {
                // Load tile of A into shared memory
                int a_row = row;
                int a_col = tileIdx * TILE_SIZE + threadIdx.x;
                if (a_row < N && a_col < N) {
                    As[threadIdx.y][threadIdx.x] = A[a_row * N + a_col];
                } else {
                    As[threadIdx.y][threadIdx.x] = 0.0f;
                }

                // Load tile of B into shared memory
                int b_row = tileIdx * TILE_SIZE + threadIdx.y;
                int b_col = col;
